void main() => runApp(const ThreeTrioApp());

class ThreeTrioApp extends StatelessWidget {
  const ThreeTrioApp({super.key});
  @override Widget build(BuildContext context) => MaterialApp(
    debugShowCheckedModeBanner: false, title: '3TRIO', theme: AppTheme.theme, home: const HomeShell());
}

class AppTheme {
  static ThemeData get theme => ThemeData(
    brightness: Brightness.dark, useMaterial3: true, scaffoldBackgroundColor: const Color(0xFF07080C),
    colorScheme: const ColorScheme.dark(primary: Color(0xFFE5485D), secondary: Color(0xFF8A6CFF), surface: Color(0xFF11131A)),
    textTheme: GoogleFonts.interTextTheme(ThemeData.dark().textTheme).apply(bodyColor: const Color(0xFFF4F2F3), displayColor: Colors.white),
    navigationBarTheme: NavigationBarThemeData(backgroundColor: const Color(0xFF090A0F), indicatorColor: const Color(0xFF2A141A), labelTextStyle: WidgetStatePropertyAll(TextStyle(fontSize: 11, fontWeight: FontWeight.w600)), height: 70),
    chipTheme: ChipThemeData(backgroundColor: const Color(0xFF171923), side: const BorderSide(color: Color(0xFF292C36)), shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(22))),
  );
}

class HomeShell extends StatefulWidget { const HomeShell({super.key}); @override State<HomeShell> createState()=>_HomeShellState(); }
class _HomeShellState extends State<HomeShell> {
  int index=0;
  final pages=const [DiscoverPage(), FeedPage(), MapPage(), LikesPage(), MessagesPage()];
  final labels=['Discover','Feed','Map','Likes','Messages'];
  final icons=[Icons.explore_outlined,Icons.dynamic_feed_outlined,Icons.map_outlined,Icons.favorite_border,Icons.chat_bubble_outline];
