class MapPainter extends CustomPainter{ @override void paint(Canvas c,Size s){final p=Paint()..color=Colors.white.withOpacity(.06)..strokeWidth=1;for(var x=0;x<s.width;x+=45)c.drawLine(Offset(x,0),Offset(x,s.height),p);for(var y=0;y<s.height;y+=45)c.drawLine(Offset(0,y),Offset(s.width,y),p);final q=Paint()..color=const Color(0xFFE5485D);for(final o in [Offset(s.width*.22,s.height*.25),Offset(s.width*.72,s.height*.34),Offset(s.width*.38,s.height*.68),Offset(s.width*.78,s.height*.72)])c.drawCircle(o,7,q);} @override bool shouldRepaint(covariant CustomPainter old)=>false;}

