class _Badge extends StatelessWidget{final IconData icon;final String label;const _Badge({required this.icon,required this.label});@override Widget build(BuildContext c)=>Container(padding:const EdgeInsets.symmetric(horizontal:9,vertical:6),decoration:BoxDecoration(color:Colors.black54,borderRadius:BorderRadius.circular(20)),child:Row(mainAxisSize:MainAxisSize.min,children:[Icon(icon,size:13),const SizedBox(width:4),Text(label,style:const TextStyle(fontSize:11))]));}
class _Pill extends StatelessWidget{final String text;const _Pill(this.text);@override Widget build(BuildContext c)=>Chip(label:Text(text,style:const TextStyle(fontSize:11)));}
class _RoundAction extends StatelessWidget{final IconData icon;final bool active;final VoidCallback onTap;const _RoundAction({required this.icon,required this.onTap,this.active=false});@override Widget build(BuildContext c)=>GestureDetector(onTap:onTap,child:Container(width:56,height:56,decoration:BoxDecoration(shape:BoxShape.circle,color:active?const Color(0xFF342044):const Color(0xFF181A22),border:Border.all(color:active?const Color(0xFF8A6CFF):Colors.white12)),child:Icon(icon,color:active?const Color(0xFFBBAAFF):Colors.white,size:25)));}
class _Stub extends StatelessWidget{final String title;const _Stub(this.title);@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:Text(title)),body:Center(child:Text(title)));}
class CallPage extends StatelessWidget{final bool video;const CallPage({super.key,this.video=false});@override Widget build(BuildContext c)=>Scaffold(backgroundColor:Colors.black,body:Center(child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[Icon(video?Icons.videocam:Icons.call,size:60),const SizedBox(height:15),const Text('Real-time call service ready for WebRTC integration'),const SizedBox(height:20),FilledButton(onPressed:()=>Navigator.pop(c),child:const Text('End call'))])));}
void _toast(BuildContext c,String s){ScaffoldMessenger.of(c).showSnackBar(SnackBar(content:Text(s),behavior:SnackBarBehavior.floating));}
